import torch
import torch.nn.functional as F

# %% shifted
def shifted(window):
    return window[:, :-1], window[:, 1:]

# %% position
def position(ids, p):
    return p["position"][:ids.size(1)]

# %% embed
def embed(ids, p):
    return p["token"][ids] + position(ids, p)

# %% causal_mask
def causal_mask(scores):
    return scores.masked_fill(~torch.ones(scores.size(-2), scores.size(-1), dtype=torch.bool).tril(), -torch.inf)

# %% head_weights
def head_weights(x, p):
    b, t, width = x.shape
    h = p.heads
    q, k = [(x @ p[key]).reshape(b, t, h, width // h).transpose(1, 2) for key in ("q", "k")]
    scores = q @ k.transpose(-2, -1) / (width // h) ** 0.5
    return causal_mask(scores).softmax(-1)

# %% merge_heads
def merge_heads(heads):
    return heads.transpose(1, 2).reshape(heads.size(0), heads.size(2), -1)

# %% attention
def attention(x, p):
    b, t, width = x.shape
    v = (x @ p["v"]).reshape(b, t, p.heads, width // p.heads).transpose(1, 2)
    return merge_heads(head_weights(x, p) @ v) @ p["out"]

# %% pre_norm
def pre_norm(x):
    return F.layer_norm(x, (x.size(-1),))

# %% ffn
def ffn(x, p):
    return F.relu(x @ p["up"]) @ p["down"]

# %% block
def block(x, p):
    h = x + attention(pre_norm(x), p)
    return h + ffn(pre_norm(h), p)

# %% lm_head
def lm_head(x, p):
    return x @ p["lm"]

# %% logits
def logits(x, p):
    z = block(x, p)
    if p.layers == 2:
        second = {k: p[k + "2"] if k in ("q", "k", "v", "out", "up", "down") else v for k, v in p.items() if not k.endswith("2")}
        class Layer(dict):
            pass
        second = Layer(second)
        second.heads = p.heads
        second.layer = 1
        z = block(z, second)
    return lm_head(z, p)

# %% loss_fn
def loss_fn(scores, targets):
    return F.cross_entropy(scores.flatten(0, 1), targets.flatten())

# %% update
def update(optimizer):
    optimizer.step()

